const createChildPortions = (portionTypeKey, parentId, sequence) => {
    const templates = CHILD_PORTION_TEMPLATES[portionTypeKey] || CHILD_PORTION_TEMPLATES.room;
    const paddedSequence = String(sequence).padStart(2, '0');
    return templates.map((template, index) => (Object.assign(Object.assign({}, template), { id: `cp-${parentId}-${index + 1}`, portionName: `${template.portionName}-${paddedSequence}` })));
};
const createMockPortion = (id, portionTypeKey, sequence) => {
    const portionType = PORTION_TYPES.find((type) => type.key === portionTypeKey) || PORTION_TYPES[0];
    const defaults = PORTION_TYPE_DEFAULTS[portionTypeKey] || PORTION_TYPE_DEFAULTS.room;
    const paddedSequence = String(sequence).padStart(2, '0');
    const portionName = `${defaults.prefix}-${paddedSequence}`;
    return {
        id,
        portionName,
        portionTypeKey,
        portionType: portionType.descr,
        workCategory: defaults.workCategory,
        measurementName: defaults.measurementName,
        scope: sequence % 2 === 0 ? 'First Floor' : 'Ground Floor',
        uom: defaults.uom,
        description: `${portionType.descr.replace(' Type', '')} mock portion ${sequence}`,
        status: sequence % 5 === 0 ? 'Completed' : 'In Progress',
        measurements: [
            { id: `m-${id}-1`, measurementName: 'Length', value: String(8 + sequence), uom: 'Ft', description: 'Mock length' },
            { id: `m-${id}-2`, measurementName: 'Width', value: String(5 + sequence), uom: 'Ft', description: 'Mock width' },
        ],
        materials: [
            { id: `mat-${id}-1`, materialName: 'Cement', quantity: String(6 + sequence), uom: 'Bags', description: 'Mock material quantity' },
            { id: `mat-${id}-2`, materialName: 'Sand', quantity: String(sequence), uom: 'Cum', description: 'Mock material quantity' },
        ],
        childPortions: createChildPortions(portionTypeKey, id, sequence),
        metrics: [
            {
                id: `met-${id}-1`,
                metricName: `${portionType.descr.replace(' Type', '')} Quantity`,
                metricType: 'Fixed',
                quantity: String(10 * sequence),
                uom: defaults.uom,
                description: 'Mock fixed metric',
            },
            {
                id: `met-${id}-2`,
                metricName: `${portionType.descr.replace(' Type', '')} Total`,
                metricType: 'Accumulative',
                quantity: String(15 * sequence),
                uom: defaults.uom,
                description: 'Mock accumulative metric',
            },
        ],
    };
};
const buildPortionRecords = () => {
    const records = SEED_PORTION_RECORDS.map((record, index) => (Object.assign(Object.assign({}, record), { childPortions: record.childPortions.length
            ? record.childPortions
            : createChildPortions(record.portionTypeKey, record.id, index + 1) })));
    let nextId = 100;
    PORTION_TYPES.forEach((portionType) => {
        const existingCount = records.filter((record) => record.portionTypeKey === portionType.key).length;
        for (let index = existingCount + 1; index <= 5; index += 1) {
            records.push(createMockPortion(nextId, portionType.key, index));
            nextId += 1;
        }
    });
    return records;
};
const PORTION_RECORDS = buildPortionRecords();
export const listPortionManagementRecords = () => PORTION_RECORDS.map((record) => (Object.assign(Object.assign({}, record), { measurements: record.measurements.map((row) => (Object.assign({}, row))), materials: record.materials.map((row) => (Object.assign({}, row))), childPortions: record.childPortions.map((row) => (Object.assign({}, row))), metrics: record.metrics.map((row) => (Object.assign({}, row))) })));
export const getPortionManagementRecordById = (id) => listPortionManagementRecords().find((record) => record.id === id);
export const createDraftPortionManagementRecord = (portionTypeKey = 'room') => {
    const portionType = PORTION_TYPES.find((type) => type.key === portionTypeKey) || PORTION_TYPES[0];
    return {
        id: 0,
        portionName: '',
        portionTypeKey: portionType.key,
        portionType: portionType.descr,
        workCategory: '',
        measurementName: '',
        scope: '',
        uom: '',
        description: '',
        status: 'In Progress',
        measurements: [],
        materials: [],
        childPortions: [],
        metrics: [],
    };
};
